"""Regression tests for the Moirai 2.0 forecaster."""

import numpy as np
import pandas as pd
import pytest
from skbase.utils.dependencies import _check_estimator_deps

from sktime.datasets import load_airline
from sktime.forecasting.moirai2 import Moirai2Forecaster

# Reference forecasts were generated by uni2ts's Moirai2Forecast/Moirai2Module,
# called directly (not through sktime), following the "Getting Started" example
# in the uni2ts README (https://github.com/SalesforceAIResearch/uni2ts).
_MOIRAI2_REFERENCE_CASES = [
    pytest.param(
        {"checkpoint_path": "Salesforce/moirai-2.0-R-small"},
        [
            474.166778564,
            396.643981934,
            348.568054199,
        ],
        id="default-context-length",
    ),
    pytest.param(
        {"checkpoint_path": "Salesforce/moirai-2.0-R-small", "context_length": 100},
        [
            467.202758789,
            400.953796387,
            362.836059570,
        ],
        id="context-length-100",
    ),
]


@pytest.mark.skipif(
    not _check_estimator_deps(Moirai2Forecaster, severity="none"),
    reason="run test only if Moirai2Forecaster soft dependencies are present",
)
@pytest.mark.parametrize(
    "forecaster_kwargs,expected_head",
    _MOIRAI2_REFERENCE_CASES,
)
def test_moirai2_airline_predictions_match_uni2ts_reference(
    forecaster_kwargs, expected_head
):
    """Moirai 2.0 predictions match the original uni2ts Moirai2Forecast pipeline."""
    y = load_airline()
    y_train = y.iloc[:-16]
    fh = np.arange(1, 17)
    forecaster = Moirai2Forecaster(use_source_package=False, **forecaster_kwargs)

    y_pred = forecaster.fit(y_train, fh=fh).predict(fh=fh)

    np.testing.assert_allclose(
        y_pred.iloc[:3].to_numpy(),
        np.asarray(expected_head, dtype=np.float32),
        rtol=1e-5,
        atol=1e-4,
    )


# ---------------------------------------------------------------------------
# Regression tests for issue #11535 – YS-JAN and similar compound freq aliases
# ---------------------------------------------------------------------------


@pytest.mark.parametrize(
    "freq_str,expected",
    [
        # compound aliases produced by PeriodIndex.to_timestamp()
        ("YS-JAN", "Y"),
        ("YS-DEC", "Y"),
        ("AS-JAN", "Y"),
        ("AS-OCT", "Y"),
        ("QS-JAN", "Q"),
        ("QS-MAR", "Q"),
        ("QS-APR", "Q"),
        # plain aliases – must still work
        ("MS", "M"),
        ("ME", "M"),
        ("QS", "Q"),
        ("QE", "Q"),
        ("YS", "Y"),
        ("YE", "Y"),
        # pass-through for unrecognised aliases
        ("D", "D"),
        ("h", "h"),
        ("W-SUN", "W-SUN"),  # weekly with anchor – pass-through unchanged
    ],
)
def test_infer_freq_compound_aliases(freq_str, expected):
    """infer_freq must normalise compound pandas freq aliases to period strings.

    Regression test for GitHub issue #11535:
    ``Moirai2Forecaster`` failed with ``ValueError: YS-JAN is not supported as
    period frequency`` when fitted on ``Longley`` (PeriodIndex with freq Y-DEC)
    because ``PeriodIndex.to_timestamp()`` returns a DatetimeIndex whose
    ``pd.infer_freq`` yields compound aliases like ``YS-JAN``.
    """
    forecaster = Moirai2Forecaster.__new__(Moirai2Forecaster)
    idx = pd.date_range("2000-01-01", periods=4, freq=freq_str)
    result = forecaster.infer_freq(idx)
    assert result == expected, (
        f"infer_freq({freq_str!r}) == {result!r}, expected {expected!r}"
    )


def test_infer_freq_period_index():
    """infer_freq returns the PeriodIndex.freq object unchanged for PeriodIndex inputs."""
    forecaster = Moirai2Forecaster.__new__(Moirai2Forecaster)
    # Longley-style annual PeriodIndex (Y-DEC)
    idx = pd.period_range("1947", periods=16, freq="Y-DEC")
    result = forecaster.infer_freq(idx)
    # Should return the freq object directly, not a string
    assert result == idx.freq
